C = dict(id='GL-19', title='Wallet Payment Solutions', group='Digital and Technology', level=4,
 summary='Design and test a safe payment-wallet journey for a small business using a licensed partner, with clear fees, receipts, refunds and fraud controls.',
 outcomes=['Explain how a wallet payment moves from tap to settlement.', 'Set up a test-mode payment flow with receipts and refunds.', 'Analyse failed payments, fees and chargebacks.', 'Create a customer payment guide and a fraud-control checklist.', 'Evaluate the journey with measures such as success rate and time to pay.'],
 task='Build and test a wallet payment journey in test mode for one small business, covering pay, receipt, failure, refund and reconciliation.',
 cond='A licensed payment partner\'s test mode (no real money), a simple storefront or form, a spreadsheet, a mentor with payments experience and a peer circle. About 10 weeks part-time.',
 std='Test mode only; success, failure and refund paths all tested; fees calculated correctly; every transaction reconciled to a record; customer guide readable in plain words; no card or account numbers stored by you.',
 who='Small-business owners, shop staff, finance and support staff, junior developers, college learners.', req='Basic computer skills.',
 safety='Use only a licensed partner and its test mode. Never store card numbers, passwords or keys. Holding customer money needs a licence: this course does not.',
 mods=[
 ('How a wallet payment moves', 'Follow the money step by step.', ['Customer authorises; the wallet provider checks funds and identity.', 'Merchant is told yes or no; money settles later.', 'Fees are taken before settlement.', 'Records on both sides must match.'], 'A 100.00 sale with a 2% fee settles as 98.00 two days later; ledger shows sale, fee and settlement. Amounts are in your currency.', 'Draw the flow with arrows and time.', 'Flow shows each party and time.'),
 ('Choosing a partner', 'Pick on safety and fit, not on price alone.', ['Licensed and regulated; clear terms.', 'Fees: percent, fixed, refund and dispute fees.', 'Settlement time; support; local methods.', 'Data handling and security.'], 'Partner A 2.0% + 0.20; partner B 1.6% + 0.50 (an estimate; check your market). On a 10.00 sale: A = 0.40, B = 0.66, so A is cheaper for small sales.', 'Compare three partners on a table.', 'Fees calculated on three sale sizes.'),
 ('Test mode set-up', 'Always rehearse without real money.', ['Create a test account; use test credentials supplied.', 'Link a simple checkout.', 'Use test wallets to simulate success and failure.', 'Keep keys private and out of documents.'], 'Test wallet 1 always succeeds; test wallet 2 declines for no funds; both paths must show a clear message.', 'Run 10 test payments.', 'All ten recorded.'),
 ('Receipts and records', 'Customers and tax offices need clear proof.', ['Receipt: date, seller, items, taxes, total, reference.', 'Number receipts in order.', 'Send by email or message with consent.', 'Keep records for the legal period.'], 'Receipt 000127: 3 items, tax 5.00, total 55.00, reference matches the partner\'s record.', 'Design a receipt and send one in test mode.', 'Receipt has all fields.'),
 ('Failures and refunds', 'Things go wrong: plan for them.', ['Common failures: low funds, timeout, wrong details.', 'Say what happened and what to do next.', 'Refund rules: when, how long, who pays the fee.', 'Avoid double charges.'], 'A timeout charges twice; the guide explains the second charge is released in 3 days or refunded now on request.', 'Test 3 failures and 2 refunds.', 'Messages are clear and kind.'),
 ('Fraud and security', 'Protect the customer and the shop.', ['Signs: unusual size, rushed buyers, mismatched details.', 'Use partner tools for checks.', 'Limit who can refund.', 'Never ask for a password or code.'], 'Order of 40 phones in one go from a new account: hold and verify.', 'Write a fraud checklist.', 'Checklist has actions, not just signs.'),
 ('Reconcile and measure', 'Match every payment to a record.', ['Daily match: partner report versus own sales log.', 'Investigate any gap.', 'Measures: success rate, time to pay, refund rate.', 'Chargebacks: reasons and prevention.'], '100 attempts: 93 succeeded = 93% success; 4 refunded = 4%; average time to pay 38 seconds.', 'Reconcile 20 transactions and compute measures.', 'Reconciliation has no unexplained gap.'),
 ('Guide and review', 'Teach customers and improve.', ['One-page guide with pictures.', 'Test it with three real users.', 'Fix confusing steps.', 'Plan 90 days.'], 'Users misread "Authorise"; the screen is changed to "Pay 55.00 now". Amounts are in your currency.', 'Write, test and revise the guide.', 'Three users complete it alone.')],
 quiz=[('What is settlement?', 'The partner paying the merchant after a sale.'), ('Why test mode?', 'To rehearse without real money.'), ('What is in a receipt?', 'Date, seller, items, taxes, total and reference.'), ('Compute a fee: 2% + 0.20 on 10.00 (in your currency).', '0.20 + 0.20 = 0.40 (in your currency).'), ('Name two failure causes.', 'Low funds and timeout.'), ('Who must hold the licence for holding money?', 'The licensed partner, not this course.'), ('What do you never store?', 'Card numbers, passwords, keys.'), ('What is reconciliation?', 'Matching payments to records.'), ('A sign of fraud?', 'Unusually large or rushed order with mismatched details.'), ('How is success rate computed?', 'Successful payments divided by attempts.')],
 rubric=[('Safe set-up', 'Test mode and keys protected', 'Access limited and reviewed'), ('Flows', 'Pay, fail, refund tested', 'Edge cases covered'), ('Records', 'Receipts and reconciliation', 'No gaps over two weeks'), ('Fraud and security', 'Checklist with actions', 'Checklist applied to cases'), ('Customer guide', 'Plain guide', 'Three users succeed alone')],
 jobs=[('Payments support agent', 'Helps with failed payments'), ('Shop finance assistant', 'Reconciles daily sales'), ('E-commerce operations assistant', 'Runs checkout and refunds'), ('Junior payments analyst', 'Tracks success and fraud')],
 next='Online Currency Exchange Concepts; E-Commerce Growth Marketing; Mobile Application Testing Services.',
 local='Payment rules, licences and which wallets people use differ greatly by place: check the regulator and local methods.',
 evidence='Your evidence: flow diagram, partner comparison, ten test payments, receipt, failure and refund tests, fraud checklist, reconciliation and guide.',
 ladder=[('Basics of paying', 'Pay with a wallet, check the receipt and explain what happens when a payment fails. Notes: use a small real payment you already make, with a trusted adult if needed. Standard: you can find the receipt, the amount and the reference.'), ('Awareness', 'Describe how a wallet links to a bank or card, what a wallet provider holds, and the main risks (theft, wrong payee, scam). Notes: compare two public wallet explanations in a table. Standard: each risk has a plain action to reduce it.'), ('Foundation', 'Draw the payment journey of one small shop: pay, receipt, failure, refund. Notes: paper map with a time and a person at each step. Standard: no step without an owner and a record.'), ('Practitioner', 'Run the journey in test mode: five payments, one failure, one refund, and match them to a day sheet. Notes: test mode only; no real money. Standard: the day sheet and the test records agree to the last unit.'), ('Specialist', 'Build and test a wallet payment journey in test mode for one small business, with pay, receipt, failure, refund and reconciliation. Notes: write limits, identity checks and a dispute step. Standard: all paths tested, totals reconcile, disputes have a deadline.'), ('Advanced', 'Lead a rollout across several shops with limits, monitoring and a fraud response. Notes: add a daily exception report and a licence check for the provider. Standard: exceptions are cleared within one day and the provider is licensed for the place.'), ('Super expert', 'Set the wallet onboarding, limits and dispute method and teach the support staff who use it. Notes: re-read the payment and identity rules for the place each year and update the checklist.')])

C['deep'] = dict(mods=[
 ('Thinking payment is done when the customer taps.', 'Authorised on Monday, settled on Wednesday, minus the fee.', 'When does money reach you?'),
 ('Picking the lowest percent without the fixed fee.', 'On 10.00 sales the 1.6% + 0.50 partner costs more than 2.0% + 0.20. Amounts are in your currency.', 'Which partner is cheaper at your average sale?'),
 ('Pasting keys into documents.', 'Keys live only in the partner\'s settings and a protected store.', 'Where are your keys?'),
 ('A receipt without a reference.', 'The reference ties the receipt to the partner record.', 'Does every receipt carry one?'),
 ('Refunding without a rule.', 'Refund within 14 days, fee not returned.', 'What is your refund rule?'),
 ('Letting any helper refund.', 'Only two named roles may refund.', 'Who can refund?'),
 ('Skipping the daily match.', 'A 3.00 gap is a missed fee; found on day 1. Amounts are in your currency.', 'What gaps did you find?'),
 ('A guide that assumes knowledge.', 'Users test "Pay 55.00 now" and complete it alone. Amounts are in your currency.', 'How many users succeeded?')],
 gloss=[('Authorisation', 'The wallet approving a payment.'), ('Settlement', 'Money paid to the merchant.'), ('Chargeback', 'A buyer disputes through their bank.'), ('Test mode', 'A safe mode with no real money.'), ('Reconciliation', 'Matching records.'), ('Tokenisation', 'Replacing card data with a safe code.')],
 cases=[('Double charge', 'A customer sees two charges after a timeout.', 'What do you do?', 'Check the partner record, release or refund the duplicate, tell the customer when.'),
        ('Large new order', 'A new account orders 40 phones.', 'Next step?', 'Hold, verify buyer and address, and use partner fraud tools.')])
C['deep']['extra'] = [
 ['Learn the difference between card, wallet and bank transfer flows.', 'Note which methods your customers use most.'],
 ['Read the partner\'s terms on holds and reserves.', 'Check support hours and escalation.'],
 ['Rotate test keys after sharing a screen.', 'Document each test in a log.'],
 ['Show taxes separately on the receipt.', 'Store receipts for the legal period.'],
 ['Tell the customer how long a refund takes.', 'Block repeated refunds to the same account for review.'],
 ['Set daily limits for new accounts.', 'Review declined payments for patterns.'],
 ['Reconcile weekly as well as daily.', 'Track fee percent over time.'],
 ['Add the support contact on the screen.', 'Update the guide whenever the screen changes.']]

_ex = ['A 100.00 sale with a 2% fee settles as 98.00 two days later; the ledger shows sale, fee and settlement as three lines. Amounts are in your currency.', 'Partner A 2.0% + 0.20; partner B 1.6% + 0.50. On a 10.00 sale A costs 0.40 and B 0.66, so A is cheaper for small sales. Amounts are in your currency.', 'Test wallet 1 always succeeds; wallet 2 declines for no funds; wallet 3 times out. Each path shows a clear message and is logged.', "Receipt 000127: 3 items, tax 5.00, total 55.00, reference ties to the partner's record. Amounts are in your currency.", 'A timeout charges twice. The guide explains the second charge is released in 3 days or refunded now on request.', 'Order of 40 phones from a new account: held, buyer verified by phone, and released after checks.', '100 attempts: 93 succeeded (93%), 4 refunded (4%), average time to pay 38 seconds. The target was 90%.', "Users misread 'Authorise'. The screen changes to 'Pay 55.00 now' and three users complete it alone. Amounts are in your currency."]
_extra = ['Draw the journey from basket to receipt.', 'Check which wallets are common among your customers.', 'Keep test keys in a protected place only.', 'Write the exact wording for payment failure messages.', 'Check support hours and escalation of the partner.', 'Record every refund with a reason.', 'Check whether tax needs to be shown separately.', 'Keep daily and weekly reconciliation notes.', 'Limit who may refund or change prices.', 'Alert customers if a payment is pending.', 'Check how chargebacks are handled.', 'Set daily limits for new accounts.', 'Test the journey on a slow phone.', 'Update the guide when screens change.', 'Keep a list of lessons for each test cycle.', 'Plan a pilot with a licensed partner before any real money.']
C['deep']['mods'] = [(m[0], _ex[i], m[2]) for i, m in enumerate(C['deep']['mods'])]
C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Trace one 20 unit payment through five steps on paper: customer taps pay, wallet app sends a token, partner checks it, the bank approves, and the shop receives a confirmation.', 'Learn three terms: authorise, capture and settle. Authorise reserves the money, capture claims it, and settle moves it to your account, often one to three working days later.'], ['Score three licensed partners from 1 to 5 on fee clarity, support response, test tools, payout speed and reporting, and favour the one with the highest total, not the lowest price.', 'Ask each partner in writing for their list of fees, their payout schedule and what they do when a payment is disputed, and keep the replies in a folder.'], ['Work only with test keys and fake card numbers supplied by the partner, and keep the secret key out of web pages, shared documents and screenshots.', 'Run at least ten test payments: five that succeed, three that are declined, and two that time out, and note exactly what the screen shows in each case.'], ['Send a receipt to every customer within one minute, showing date, items, total, tax if any, a payment reference and a contact for questions.', "Keep a monthly record file with one row per payment and store a copy outside the system; check that the number of rows equals the partner's report each week."], ['Write a plain message for each failure: card declined, timeout, duplicate charge and wrong amount, telling the customer what happened and the next step in under 25 words.', 'Set a refund routine: confirm the order, refund to the original method, send a message, and record the date; aim to complete it within two working days.'], ['Add simple limits: block more than five failed attempts per card in an hour, flag orders far above your usual size, and require two people to approve large refunds.', 'Keep software and passwords updated, turn on two-step sign-in for every account, and remove access the day a team member leaves.'], ["Each week, match the partner's payout report to your own records line by line; any difference above 1 unit or any missing payment goes on a short follow-up list.", 'Track three measures monthly: the percentage of payments that succeed, the average time to payout and the refund rate, and compare month to month.'], ['Write a one-page customer guide with three steps to pay, what to do if it fails and how to ask for a refund, in language a ten-year-old could follow.', 'Review the pilot after two weeks with test users, listing what confused them, and only plan real money after a licensed partner and an adviser have approved the setup.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]

_dupfix = {1: 'A 250.00 online sale with a 1.5% fee settles as 246.25 three days later; the ledger shows sale, fee and payout as separate lines so the owner can match the bank statement. Amounts are in your currency.', 2: 'Partner C charges 1.0% + 0.60; partner D charges 2.5% with no fixed fee. On a 40.00 sale C costs 1.00 and D costs 1.00, so they tie; above 40.00 C is cheaper. Amounts are in your currency.', 3: "In test mode a card marked 'expired' must show 'Please use another card' and record no sale, and a card marked 'slow' must show a waiting message and a retry after 20 seconds.", 4: "Receipt 000342: 2 items, tax 3.20, total 43.20, paid by wallet, with the partner's reference printed so a customer can quote it in a complaint. Amounts are in your currency.", 5: "A customer's phone loses signal during payment and nothing confirms. The page tells her to wait 10 minutes, check her bank, and gives the number to call; the shop finds the payment and confirms by message.", 6: "Ten small payments of 49.00 arrive in 3 minutes from one device with different cards. The system pauses them, the shop asks for the cardholder's contact, and two are cancelled as stolen cards.", 7: 'In a week there were 300 attempts, 276 succeeded (92%), 9 were refunded (3%), and 15 failed for no funds. Matching the payout against the bank left a difference of 0.00. Amounts are in your currency.', 8: "A test user pressed 'Cancel' thinking it meant 'Back'. The screen now says 'Go back' and 'Cancel payment' on separate lines, and five users choose correctly."}
C['deep']['mods'] = [(m[0], _dupfix.get(i + 1, m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]

_dupfix2 = {1: 'A bakery sells a cake for 250.00 and the wallet partner keeps 1.5%. Three days later 246.25 arrives, and the owner can tie the bank line back to the sale and the fee in the records.'}
C['deep']['mods'] = [(m[0], _dupfix2.get(i + 1, m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]
C['intro_add'] = ['You will trace a wallet payment from tap to settlement and use the terms authorise, capture and settle correctly when talking to a partner.', 'You will score licensed partners on fees, support, tools, payout speed and reporting, and justify your choice with written evidence.', 'You will run ten rehearsal payments with test keys, including declines and timeouts, and keep secret keys out of any shared place.', 'You will issue receipts quickly and keep a monthly payment log, so every sale can be proved to a customer or a tax office.', 'You will write plain messages for four common failures and follow a fixed refund routine, keeping customers informed and trusting.', 'You will set practical limits, approvals and sign-in protections that make payment fraud harder without slowing honest customers.', 'You will match each payout report to your own records and track three monthly measures, so missing money is found within a week.', 'You will write a short customer guide and review a pilot with test users, leaving the shop ready for a safe, approved launch.']
